(() => {
'use strict';
const $=id=>document.getElementById(id); const screen=$('screen');
let APP_VERSION='';
async function loadAppStatus(){try{const d=await api('/api/status');APP_VERSION=d.version||'';document.querySelectorAll('.appVersion').forEach(x=>x.textContent=APP_VERSION?`V${APP_VERSION}`:'');}catch(e){}} const error=$('error');
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(path,opts={}){const ctl=new AbortController();const t=setTimeout(()=>ctl.abort(),10000);try{const r=await fetch(path,{credentials:'include',headers:{'Content-Type':'application/json',...(opts.headers||{})},signal:ctl.signal,...opts});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||d.message||'خطای سرور');return d}finally{clearTimeout(t)}}
function showError(msg){error.className='error';error.textContent=msg} function clearError(){error.className='hidden';error.textContent=''}
window.addEventListener('error',e=>showError('خطای غیرمنتظره در رابط کاربری: '+e.message));
async function init(){try{const s=await api('/api/setup/status');s.setup_required?setup():login()}catch(e){showError('ارتباط با سرور برقرار نشد.');}}
function setup(){loadAppStatus();hideMobileNav();screen.innerHTML=`<div class="card"><div class="brand">SMART MARKET</div><h2>راه‌اندازی اولیه</h2><p class="muted">مدیر اولیه را ایجاد کنید.</p><input id="u" placeholder="نام کاربری"><input id="p" type="password" placeholder="رمز عبور حداقل ۱۰ کاراکتر"><button id="go">ایجاد مدیر</button></div>`;$('go')?.addEventListener('click',async()=>{clearError();try{await api('/api/setup',{method:'POST',body:JSON.stringify({username:$('u').value,password:$('p').value})});login()}catch(e){showError(e.message)}})}
function login(){loadAppStatus();hideMobileNav();screen.innerHTML=`<div class="card"><div class="brand">SMART MARKET</div><h2>ورود</h2><input id="u" placeholder="نام کاربری"><input id="p" type="password" placeholder="رمز عبور"><button id="go">ورود</button></div>`;$('go')?.addEventListener('click',async()=>{clearError();try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('u').value,password:$('p').value})});dashboard()}catch(e){showError(e.message)}})}
async function loadMarkets(){try{const ms=await api('/api/markets?active_only=true');const sel=$('market');if(!sel)return;const current=sel.value;sel.innerHTML=(ms.items||ms).map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('')||'<option value="">انتخاب بازار</option>';if(current&&Array.from(sel.options).some(o=>o.value===current))sel.value=current;}catch(e){showError('فهرست بازارها بارگذاری نشد: '+e.message)}}
async function loadDiscoverySources(){try{const d=await api('/api/discovery/sources');const box=$('sourceOptions');if(!box)return;box.innerHTML=(d.sources||[]).map(s=>`<label class="sourceChoice"><input type="checkbox" value="${esc(s.key)}" ${['web','places'].includes(s.key)?'checked':''} ${s.configured?'':'disabled'}><span>${esc(s.label)}</span><small>${s.configured?'آماده':'نیازمند تنظیم'}</small></label>`).join('')}catch(e){showError('فهرست منابع بارگذاری نشد: '+e.message)}}
async function tradeRulesCenter(){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری Country & Trade Rules...</div>';try{const market=$('market')?.value||'';const ms=await api('/api/markets?active_only=true');const m=(ms.items||ms).find(x=>x.name===market);if(!m){showError('بازار انتخاب‌شده پیدا نشد.');return}const d=await api('/api/markets/'+encodeURIComponent(m.id)+'/trade-readiness');$('results').innerHTML=`<div class="card"><div class="row"><div><h2>Country & Trade Rules · V24.21</h2><p class="muted">${esc(d.market.name)} · این صفحه فقط Ruleهای ثبت‌شده و منبع‌دار را نشان می‌دهد؛ در نبود Rule تأییدشده، سیستم نتیجه قانونی فرض نمی‌کند.</p></div><span class="chip ${d.status==='Ready'?'ok':'miss'}">${esc(d.status)}</span></div><div class="stats"><div class="stat"><b>${esc(d.rule_count)}</b><div class="muted">Rules</div></div><div class="stat"><b>${esc(d.mandatory_count)}</b><div class="muted">Mandatory</div></div><div class="stat"><b>${esc(d.verified_count)}</b><div class="muted">Verified</div></div><div class="stat"><b>${esc(d.readiness_score)}%</b><div class="muted">Readiness</div></div></div></div>${(d.rules||[]).map(r=>`<article class="card opp"><div class="row"><b>${esc(r.title)}</b><span class="chip ${r.status==='Verified'?'ok':'miss'}">${esc(r.status)}</span></div><p>${esc(r.requirement)}</p><p class="muted">${esc(r.rule_type)} · ${r.mandatory?'Mandatory':'Optional'}${r.hs_code?' · HS '+esc(r.hs_code):''}</p><p class="muted">${esc(r.authority||'Authority not recorded')} · ${esc(r.source_title||r.source_url||'Source not recorded')}</p></article>`).join('')||'<div class="card muted">برای این بازار هنوز Rule ثبت نشده است.</div>'}` }catch(e){$('results').innerHTML='';showError(e.message)}}

function mountMobileNav(){const nav=$('mobileNav');if(!nav)return;nav.classList.remove('hidden');const setActive=(name)=>nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));nav.querySelectorAll('button').forEach(b=>b.onclick=async()=>{const n=b.dataset.nav;setActive(n);if(n==='home'){window.scrollTo({top:0,behavior:'smooth'});return}if(n==='search'){$('product')?.focus();$('product')?.scrollIntoView({behavior:'smooth',block:'center'});return}if(n==='opportunities'){await opportunityPipeline();$('results')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(n==='market'){await marketIntelligence();$('results')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(n==='operations'){await commandCenter();$('results')?.scrollIntoView({behavior:'smooth',block:'start'});return}});setActive('home')}
function hideMobileNav(){const nav=$('mobileNav');if(nav)nav.classList.add('hidden')}
async function dashboard(){clearError();try{await loadAppStatus();const d=await api('/api/dashboard'); const me=await api('/api/rbac/me'); screen.innerHTML=`<header class="card topBar"><div><div class="brand">SMART MARKET</div><p class="muted">بازار هوشمند تجارت</p></div><button id="logout" class="ghost">خروج</button></header><section class="card searchHero"><h2>جستجوی فرصت</h2><p class="muted">محصول را وارد کنید و ابتدا پایگاه داخلی را بررسی کنید؛ سپس در صورت نیاز منابع واقعی را کشف کنید.</p><div class="grid"><input id="product" placeholder="مثلاً رزین اپوکسی" autocomplete="off"><select id="market"><option value="">انتخاب بازار</option></select></div><div class="card mini"><b>منابع جستجوی خارجی</b><div id="sourceOptions" class="sourceOptions"></div><input id="customDomains" placeholder="دامنه‌های دلخواه، مثال: example.com, example.org"><p class="muted">جستجو فقط در صفحات عمومی و نمایه‌شده انجام می‌شود؛ دسترسی خصوصی یا ورود به حساب انجام نمی‌شود.</p></div><div class="primaryActions actions"><button id="search">جستجوی داخلی</button><button id="discover" class="accent">کشف منابع</button></div><div class="secondaryActions actions"><button id="workspace" class="ghost">Workspace</button><button id="pipeline" class="ghost">Pipeline</button><button id="commandCenter" class="ghost">مرکز عملیات</button><button id="actions" class="ghost">اقدام‌های پیگیری</button></div></section><section class="stats">${[['تولیدکننده','manufacturers'],['مشتری','customers'],['تقاضا','demands'],['سیگنال','signals'],['فرصت','opportunities'],['محصول','products']].map(x=>`<div class="stat"><b>${esc(d[x[1]])}</b><div class="muted">${x[0]}</div></div>`).join('')}</section><details class="toolDetails" id="advancedTools"><summary>ابزارهای تخصصی بازار و عملیات</summary><div class="toolDetailsContent"><section class="card desktopActionGroup"><p class="actionGroupTitle">هوش بازار و فرصت</p><div class="secondaryActions"><button id="benchmark" class="ghost">Price Benchmark</button><button id="marketIntel" class="ghost">Market Intelligence</button><button id="priceIntel" class="ghost">Supplier vs Market</button><button id="opIntel" class="ghost">Opportunity Intelligence</button><button id="health" class="ghost">Opportunity Health</button><button id="quality" class="ghost">Data Quality</button></div></section><section class="card desktopActionGroup"><p class="actionGroupTitle">منبع، زمان و کنترل</p><div class="secondaryActions"><button id="evidence" class="ghost">Source & Evidence</button><button id="temporal" class="ghost">Temporal Intelligence</button><button id="watchtower" class="ghost">Watchtower Alerts</button><button id="tradeRules" class="ghost">Country & Trade Rules</button><button id="compliance" class="ghost">HS & Compliance</button><button id="importCost" class="ghost">Import Cost & Duty</button><button id="tradeOptimizer" class="ghost">Trade Optimizer</button><button id="rbacCenter" class="ghost hidden">Users & Permissions</button></div></section></div></details><section class="card"><h3>کنترل اعتبار</h3><p class="muted">هر رکورد باید منبع، وضعیت تأیید و سطح اطمینان مشخص داشته باشد. داده نامشخص به‌عنوان واقعیت نمایش داده نمی‌شود.</p></section><section id="actionPanel" class="card"><div class="row"><h3>Action Center</h3><span class="chip">عملیات</span></div><div id="actionResults" class="muted">برای مشاهده اقدام‌های باز، دکمه را بزنید.</div></section><section id="results" class="resultAnchor"></section>`;await loadMarkets();await loadDiscoverySources();$('logout')?.addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});login()});$('search')?.addEventListener('click',search);$('discover')?.addEventListener('click',externalDiscovery);$('benchmark')?.addEventListener('click',priceBenchmark);$('marketIntel')?.addEventListener('click',marketIntelligence);$('priceIntel')?.addEventListener('click',supplierVsMarket);$('opIntel')?.addEventListener('click',opportunityIntelligence);$('workspace')?.addEventListener('click',opportunityWorkspace);$('pipeline')?.addEventListener('click',opportunityPipeline);$('health')?.addEventListener('click',opportunityHealth);$('quality')?.addEventListener('click',dataQualityCenter);$('evidence')?.addEventListener('click',sourceEvidenceCenter);$('temporal')?.addEventListener('click',temporalIntelligence);$('watchtower')?.addEventListener('click',watchtower);$('commandCenter')?.addEventListener('click',commandCenter);$('tradeRules')?.addEventListener('click',tradeRulesCenter);$('compliance')?.addEventListener('click',complianceCenter);$('importCost')?.addEventListener('click',importCostCenter);$('tradeOptimizer')?.addEventListener('click',tradeOptimizerCenter); if(me.permissions?.includes('user.manage')){$('rbacCenter')?.classList.remove('hidden');$('rbacCenter')?.addEventListener('click',rbacCenter)} const toolsPanel=$('advancedTools'); if(toolsPanel && window.matchMedia('(min-width:761px)').matches) toolsPanel.open=true; mountMobileNav(); $('actions')?.addEventListener('click',loadActions);$('results')?.addEventListener('click',async e=>{const b=e.target.closest('.rfqBtn'); if(b) await generateRFQ(b.dataset.id); const c=e.target.closest('.commBtn'); if(c) await loadComms(c.dataset.id); const s=e.target.closest('.sendRfq'); if(s){try{await api('/api/opportunities/'+s.dataset.op+'/rfqs/'+s.dataset.rfq,{method:'PATCH',body:JSON.stringify({status:'Sent'})}); await api('/api/opportunities/'+s.dataset.op+'/communications',{method:'POST',body:JSON.stringify({channel:'whatsapp',status:'Sent',subject:'RFQ sent',message:'RFQ '+s.dataset.rfq+' marked as sent.'})}); await loadComms(s.dataset.op)}catch(e){showError(e.message)}}})}catch(e){showError(e.message)}}
async function loadActions(){clearError();try{const d=await api('/api/action-center');$('actionResults').innerHTML=(d.items||[]).map(a=>`<article class="opp"><b>${esc(a.action_type)} · ${esc(a.status)}</b><p>${esc(a.subject||'بدون عنوان')}</p><small class="muted">سررسید: ${esc(a.due_at||'بدون تاریخ')}</small></article>`).join('')||'اقدام باز وجود ندارد.'}catch(e){showError(e.message)}}
async function externalDiscovery(){const p=$('product').value.trim();if(!p)return showError('نام محصول را وارد کنید.');const sources=Array.from(document.querySelectorAll('#sourceOptions input[type=checkbox]:checked')).map(x=>x.value);if(!sources.length)return showError('حداقل یک منبع جستجو را انتخاب کنید.');clearError();$('results').innerHTML='<div class="card">در حال کشف منابع مجاز...</div>';try{const d=await api('/api/discovery/external',{method:'POST',body:JSON.stringify({product:p,market:$('market').value,sources,domains:($('customDomains')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),max_results:20})});$('results').innerHTML=`<div class="card"><h3>کشف منابع: ${esc(p)}</h3><p class="muted">${esc(d.count)} نتیجه · ${esc(d.errors?.join(' | ')||'بدون خطا')}</p></div>${(d.results||[]).map(r=>{const c=r.candidate||{};return `<article class="card opp"><b>${esc(c.candidate_type||'Review')}</b><p>${esc(c.name||'نام شرکت نامشخص')}</p><p class="muted">${esc(c.country||'')} ${esc(c.city||'')} · اطمینان ${Math.round((c.confidence||0)*100)}%</p><a href="${esc(c.source_url||r.place?.maps_url||r.source?.url||'#')}" target="_blank" rel="noopener noreferrer">منبع</a></article>`}).join('')||'<div class="card muted">نتیجه‌ای پیدا نشد. کلید API و محدودیت‌های منبع را بررسی کنید.</div>'}` }catch(e){$('results').innerHTML='';showError(e.message)}}

async function opportunityWorkspace(){clearError();$('results').innerHTML='<div class="card">در حال آماده‌سازی Workspace...</div>';try{const ops=await api('/api/opportunities');if(!ops.length){$('results').innerHTML='<div class="card muted">هنوز Opportunity ثبت نشده است.</div>';return}const cards=ops.slice(0,20).map(o=>`<button class="oppPick" data-id="${esc(o.id)}">#${esc(o.id)} · ${esc(Math.round(o.score||0))} · ${esc(o.priority||'')} · ${esc(o.next_action||'')}</button>`).join('');$('results').innerHTML=`<div class="card"><h3>Opportunity Workspace</h3><p class="muted">یک فرصت را انتخاب کنید؛ سپس Quote، مسیر حمل، Action و Communication را از همین صفحه مدیریت کنید.</p><div class="oppList">${cards}</div></div>`;document.querySelectorAll('.oppPick').forEach(b=>b.addEventListener('click',()=>loadWorkspace(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadWorkspace(id){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری Workspace...</div>';try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/workspace');const q=d.work_queue||{};const op=d.opportunity||{};const b=d.benchmark||{};$('results').innerHTML=`<div class="card opp"><div class="brand">Workspace #${esc(op.id)}</div><p>${esc(d.product?.name||'')} · ${esc(d.customer?.name||'')} · ${esc(d.manufacturer?.name||'')}</p><div class="stats"><div class="stat"><b>${esc(q.open_actions||0)}</b><div class="muted">Open Actions</div></div><div class="stat"><b>${esc(q.quotes||0)}</b><div class="muted">Quotes</div></div><div class="stat"><b>${esc(q.routes||0)}</b><div class="muted">Routes</div></div><div class="stat"><b>${esc(q.offers||0)}</b><div class="muted">Offers</div></div></div><p>Benchmark: <b>${esc(b.weighted_median_price||b.median_price||'—')} ${esc(b.currency||'')}</b> / ${esc(b.unit||'')}</p></div><div class="card"><h3>ثبت اقدام</h3><div class="grid"><select id="wsActionType"><option>follow_up</option><option>call</option><option>whatsapp</option><option>email</option><option>rfq</option><option>meeting</option><option>note</option></select><input id="wsActionSubject" placeholder="عنوان اقدام"></div><button id="wsAddAction" class="accent">ثبت Action</button></div><div class="card"><h3>Supplier Quote سریع</h3><div class="grid"><input id="wsSupplier" placeholder="نام تأمین‌کننده"><input id="wsPrice" type="number" step="any" placeholder="قیمت واحد"><input id="wsQty" type="number" step="any" placeholder="مقدار"><input id="wsCurrency" value="USD" placeholder="ارز"><input id="wsUnit" value="kg" placeholder="واحد"><input id="wsIncoterm" value="EXW" placeholder="Incoterm"></div><button id="wsAddQuote" class="accent">ثبت Quote</button></div><div class="card"><h3>مسیر حمل سریع</h3><div class="grid"><input id="wsOrigin" placeholder="مبدأ"><input id="wsDestination" placeholder="مقصد"><input id="wsFreight" type="number" step="any" value="0" placeholder="هزینه حمل"></div><button id="wsAddRoute" class="accent">ثبت Route</button></div><div class="card"><h3>آخرین داده‌ها</h3><p>Quotes: ${(d.supplier_quotes||[]).length} · Routes: ${(d.logistics_scenarios||[]).length} · Communications: ${(d.communications||[]).length} · RFQs: ${(d.rfqs||[]).length}</p>${(d.next_actions||[]).map(a=>`<div class="mini"><b>${esc(a.action_type)}</b> · ${esc(a.status)}<br>${esc(a.subject||'')}</div>`).join('')||'<span class="muted">اقدام بازی وجود ندارد.</span>'}</div><p class="muted">${esc(d.disclaimer||'')}</p>`;bindWorkspaceActions(id)}catch(e){$('results').innerHTML='';showError(e.message)}}
function bindWorkspaceActions(id){$('wsAddAction')?.addEventListener('click',async()=>{try{await api('/api/opportunities/'+id+'/workspace/command',{method:'POST',body:JSON.stringify({command:'action',action:{action_type:$('wsActionType').value,subject:$('wsActionSubject').value||'Workspace action',status:'Planned'}})});await loadWorkspace(id)}catch(e){showError(e.message)}});$('wsAddQuote')?.addEventListener('click',async()=>{try{const unitPrice=Number($('wsPrice').value),qty=Number($('wsQty').value);if(!(unitPrice>0&&qty>0))throw new Error('قیمت و مقدار Quote باید بیشتر از صفر باشد.');await api('/api/opportunities/'+id+'/workspace/command',{method:'POST',body:JSON.stringify({command:'supplier_quote',supplier_quote:{supplier_name:$('wsSupplier').value||'Supplier',currency:$('wsCurrency').value||'USD',unit_price:unitPrice,quantity:qty,unit:$('wsUnit').value||'kg',incoterm:$('wsIncoterm').value||'EXW',status:'Unverified'}})});await loadWorkspace(id)}catch(e){showError(e.message)}});$('wsAddRoute')?.addEventListener('click',async()=>{try{if(!$('wsOrigin').value||!$('wsDestination').value)throw new Error('مبدأ و مقصد را وارد کنید.');await api('/api/opportunities/'+id+'/workspace/command',{method:'POST',body:JSON.stringify({command:'logistics_scenario',logistics_scenario:{name:'Workspace Route',origin:$('wsOrigin').value,destination:$('wsDestination').value,transport_mode:'road',freight_total:Number($('wsFreight').value||0),currency:'USD',verification_status:'Unverified'}})});await loadWorkspace(id)}catch(e){showError(e.message)}})}
async function opportunityIntelligence(){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری زنجیره فرصت...</div>';try{const ops=await api('/api/opportunities');if(!ops.length){$('results').innerHTML='<div class="card muted">هنوز Opportunity ثبت نشده است.</div>';return}const cards=ops.slice(0,12).map(o=>`<button class="oppPick" data-id="${esc(o.id)}">#${esc(o.id)} · Score ${esc(Math.round(o.score||0))} · ${esc(o.priority||'')} · ${esc(o.next_action||'')}</button>`).join('');$('results').innerHTML=`<div class="card"><h3>Opportunity Intelligence</h3><p class="muted">یک فرصت را انتخاب کنید تا Buyer، Demand، Supplier، Quote، Benchmark، Logistics، Commercial Offer و Action Center یکجا دیده شوند.</p><div class="oppList">${cards}</div></div>`;document.querySelectorAll('.oppPick').forEach(b=>b.addEventListener('click',()=>loadOpportunityIntelligence(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadOpportunityIntelligence(id){clearError();$('results').innerHTML='<div class="card">در حال تحلیل فرصت...</div>';try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/intelligence');const c=d.chain_status||{};const checks=[['Buyer',c.buyer],['Demand',c.demand],['Supplier',c.supplier],['Quote',c.quote],['Benchmark',c.benchmark],['Logistics',c.logistics],['Offer',c.commercial_offer],['Next Action',c.next_action]];$('results').innerHTML=`<div class="card opp"><div class="brand">Opportunity #${esc(d.opportunity?.id)}</div><p>${esc(d.product?.name||'')} · ${esc(d.customer?.name||'')} · ${esc(d.manufacturer?.name||'')}</p><div class="chain">${checks.map(x=>`<span class="chip ${x[1]?'ok':'miss'}">${esc(x[0])}: ${x[1]?'✓':'—'}</span>`).join('')}</div><h3>Demand</h3><p>${esc(d.demand?.quantity||'—')} ${esc(d.demand?.unit||'')} · ${esc(d.demand?.urgency||'—')} · ${esc(d.demand?.verification_status||'—')}</p><h3>Market Benchmark</h3><p>${esc(d.market_benchmark?.weighted_median_price||d.market_benchmark?.median_price||'—')} ${esc(d.market_benchmark?.currency||'')} / ${esc(d.market_benchmark?.unit||'')} · confidence ${Math.round((d.market_benchmark?.confidence||0)*100)}%</p><h3>Supplier vs Market</h3>${(d.supplier_vs_market||[]).map(x=>`<div class="mini"><b>${esc(x.supplier_name||('Quote '+x.quote_id))}</b><br>Cost: ${esc(x.normalized_landed_unit_cost??'—')} · Room: ${esc(x.market_room_per_unit??'—')} · ${esc(x.band||x.reason||'')}</div>`).join('')||'<p class="muted">داده قابل مقایسه وجود ندارد.</p>'}<h3>Commercial & Logistics</h3><p>${(d.commercial_offers||[]).length} offer · ${(d.logistics_scenarios||[]).length} route/scenario · ${(d.actions||[]).length} action</p><p class="muted">${esc(d.disclaimer||'')}</p></div>`}catch(e){$('results').innerHTML='';showError(e.message)}}

async function priceBenchmark(){const p=$('product').value.trim();if(!p)return showError('نام محصول را وارد کنید.');clearError();$('results').innerHTML='<div class="card">در حال محاسبه Benchmark...</div>';try{const ps=await api('/api/products');const hit=(ps||[]).find(x=>(x.name||'').toLowerCase()===p.toLowerCase())||(ps||[]).find(x=>(x.name||'').toLowerCase().includes(p.toLowerCase()));if(!hit){$('results').innerHTML='<div class="card muted">محصول هنوز در پایگاه داخلی ثبت نشده است.</div>';return}const d=await api('/api/market-prices/benchmark',{method:'POST',body:JSON.stringify({product_id:hit.id,market:$('market').value,unit:hit.unit||'kg',target_currency:'USD',fx_rates:{USD:1},min_effective:3})});const b=d.benchmark||{};$('results').innerHTML=`<div class="card"><h3>Price Benchmark · ${esc(hit.name)}</h3><p>وضعیت: <b>${esc(b.benchmark_status)}</b></p><p>تعداد مشاهدات: ${esc(b.observation_count)} · داده مؤثر: ${esc(b.effective_count)}</p><p>Median: ${esc(b.median_price||0)} ${esc(b.currency||'USD')} / ${esc(b.unit||'')}</p><p>Weighted Median: ${esc(b.weighted_median_price||0)} · Confidence: ${Math.round((b.confidence||0)*100)}%</p><p class="muted">این Benchmark فقط از داده‌های ثبت‌شده و نرخ‌های تبدیل صریح استفاده می‌کند و در نبود داده کافی قیمت‌سازی نمی‌کند.</p></div>`}catch(e){$('results').innerHTML='';showError(e.message)}}
async function marketIntelligence(){const p=$('product').value.trim();if(!p)return showError('نام محصول را وارد کنید.');clearError();$('results').innerHTML='<div class="card">در حال بارگذاری Market Intelligence...</div>';try{const ps=await api('/api/products');const hit=(ps||[]).find(x=>(x.name||'').toLowerCase()===p.toLowerCase())||(ps||[]).find(x=>(x.name||'').toLowerCase().includes(p.toLowerCase()));if(!hit){$('results').innerHTML='<div class="card muted">محصول در پایگاه داخلی ثبت نشده است.</div>';return}const d=await api('/api/market-prices/dashboard?product_id='+encodeURIComponent(hit.id)+'&market='+encodeURIComponent($('market').value)+'&target_currency=USD&target_unit='+encodeURIComponent(hit.unit||'kg')+'&days=90');const b=d.benchmark||{};const sd=d.source_diversity||{};const alerts=d.alerts||[];$('results').innerHTML=`<div class="card"><h3>Market Intelligence · ${esc(hit.name)}</h3><div class="stats"><div class="stat"><b>${b.weighted_median_price?Number(b.weighted_median_price).toFixed(2):'—'}</b><div class="muted">Weighted Median / ${esc(hit.unit||'kg')}</div></div><div class="stat"><b>${b.low_price?Number(b.low_price).toFixed(2):'—'} – ${b.high_price?Number(b.high_price).toFixed(2):'—'}</b><div class="muted">Market Range</div></div><div class="stat"><b>${Math.round((b.confidence||0)*100)}%</b><div class="muted">Confidence</div></div><div class="stat"><b>${sd.unique_sources||0}</b><div class="muted">Independent Sources</div></div></div><p class="muted">وضعیت Benchmark: ${esc(b.benchmark_status||'No Benchmark')} · مشاهدات: ${esc(d.observation_count||0)}</p></div><div class="card"><h3>روند ۹۰ روزه</h3>${(d.trend||[]).map(x=>`<div class="row"><span>${esc(String(x.date).slice(0,10))}</span><span>${Number(x.median).toFixed(2)} · ${esc(x.count)} مشاهده</span></div>`).join('')||'<span class="muted">داده روند کافی نیست.</span>'}</div><div class="card"><h3>Price Alerts</h3>${alerts.map(a=>`<p><b>${esc(a.band)}</b> · ${esc(a.delta_pct)}% · observation #${esc(a.observation_id)}</p>`).join('')||'<span class="muted">هشدار قیمتی ثبت‌شده‌ای در این بازه وجود ندارد.</span>'}</div>`}catch(e){$('results').innerHTML='';showError(e.message)}}

async function supplierVsMarket(){const p=$('product').value.trim();if(!p)return showError('نام محصول را وارد کنید.');clearError();$('results').innerHTML='<div class="card">در حال مقایسه قیمت تأمین‌کنندگان با Benchmark بازار...</div>';try{const ps=await api('/api/products');const hit=(ps||[]).find(x=>(x.name||'').toLowerCase()===p.toLowerCase())||(ps||[]).find(x=>(x.name||'').toLowerCase().includes(p.toLowerCase()));if(!hit){$('results').innerHTML='<div class="card muted">محصول در پایگاه داخلی ثبت نشده است.</div>';return}const sd=await api('/api/search',{method:'POST',body:JSON.stringify({product:p,market:$('market').value})});const op=(sd.opportunities||[])[0];if(!op){$('results').innerHTML='<div class="card muted">برای این محصول فرصت دارای تأمین‌کننده ثبت‌شده پیدا نشد.</div>';return}const d=await api('/api/opportunities/'+op.id+'/price-intelligence',{method:'POST',body:JSON.stringify({target_currency:'USD',target_unit:hit.unit||'kg',fx_rates:{USD:1},unit_factors:{}})});const b=d.benchmark||{};$('results').innerHTML=`<div class="card"><h3>Supplier vs Market · ${esc(hit.name)}</h3><p class="muted">Opportunity #${esc(op.id)} · Benchmark: ${b.weighted_median_price?Number(b.weighted_median_price).toFixed(2):'—'} USD/${esc(hit.unit||'kg')}</p></div>${(d.comparisons||[]).map(x=>x.comparable?`<article class="card opp"><b>${esc(x.supplier_name)}</b><p>هزینه نهایی نرمال‌شده: <b>${Number(x.normalized_landed_unit_cost).toFixed(2)} USD/${esc(x.unit)}</b></p><p>انحراف از Benchmark: ${Number(x.delta_pct).toFixed(2)}% · فضای بازار: ${Number(x.market_room_per_unit).toFixed(2)} USD/${esc(x.unit)}</p><small class="muted">${esc(x.band)}</small></article>`:`<article class="card opp"><b>Quote #${esc(x.quote_id)}</b><p class="muted">قابل مقایسه نیست: ${esc(x.reason||'conversion_unavailable')}</p></article>`).join('')||'<div class="card muted">هیچ Quote قابل مقایسه‌ای وجود ندارد.</div>'}`}catch(e){$('results').innerHTML='';showError(e.message)}}


async function dataQualityCenter(){clearError();$('results').innerHTML='<div class="card">در حال بررسی کیفیت داده‌های فرصت‌ها...</div>';try{const d=await api('/api/data-quality/opportunities?limit=100');const items=d.items||[];$('results').innerHTML=`<div class="card"><h3>Smart Data Quality Center · V24.21</h3><p class="muted">این مرکز کامل‌بودن داده، شواهد، منبع و اجزای تجاری را بررسی می‌کند؛ پیش‌بینی نتیجه معامله نیست.</p></div>${items.map(x=>`<article class="card opp"><div class="row"><b>#${esc(x.opportunity_id)} · ${esc(x.stage)}</b><span class="chip">${esc(x.status)}</span></div><div class="stats"><div class="stat"><b>${Number(x.overall_score).toFixed(0)}</b><div class="muted">Quality</div></div><div class="stat"><b>${x.gate.blocking_count}</b><div class="muted">Blockers</div></div><div class="stat"><b>${x.gate.warning_count}</b><div class="muted">Warnings</div></div></div><p class="muted">Buyer ${Number(x.entity_quality.buyer.score).toFixed(0)} · Supplier ${Number(x.entity_quality.supplier.score).toFixed(0)} · Demand ${Number(x.entity_quality.demand.score).toFixed(0)} · Verification ${Math.round(Object.values(x.verification).reduce((a,v)=>a+Number(v.score||0),0)/Math.max(1,Object.keys(x.verification).length))}</p><ul>${(x.blockers||[]).map(v=>`<li>⛔ ${esc(v)}</li>`).join('')}${(x.warnings||[]).map(v=>`<li>⚠ ${esc(v)}</li>`).join('')}</ul><button class="ghost qualityGateBtn" data-id="${esc(x.opportunity_id)}">جزئیات Gate</button><div id="quality-${esc(x.opportunity_id)}"></div></article>`).join('')||'<div class="card muted">فرصت فعالی وجود ندارد.</div>'}`;document.querySelectorAll('.qualityGateBtn').forEach(b=>b.addEventListener('click',()=>loadQualityGate(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadQualityGate(id){const box=$('quality-'+id);if(!box)return;try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/data-quality/gate');box.innerHTML=`<div class="mini"><b>Stage Gate</b><p>${d.can_advance?'✓ آماده عبور از Gate':'⛔ عبور فعلاً مسدود است'}</p>${(d.blockers||[]).map(v=>`<p>⛔ ${esc(v)}</p>`).join('')}${(d.warnings||[]).map(v=>`<p>⚠ ${esc(v)}</p>`).join('')}</div>`}catch(e){showError(e.message)}}
async function opportunityHealth(){clearError();$('results').innerHTML='<div class="card">در حال محاسبه سلامت فرصت‌ها...</div>';try{const d=await api('/api/opportunities/health?limit=100');const items=d.items||[];$('results').innerHTML=`<div class="card"><h3>Opportunity Health · V24.21</h3><p class="muted">شاخص عملیاتی سلامت، کیفیت داده و فوریت اقدام را نشان می‌دهد؛ پیش‌بینی نتیجه معامله نیست.</p></div>${items.map(x=>`<article class="card opp"><div class="row"><b>#${esc(x.opportunity_id)} · ${esc(x.stage)}</b><span class="chip">${esc(x.label)}</span></div><div class="stats"><div class="stat"><b>${Number(x.overall_health).toFixed(0)}</b><div class="muted">Health</div></div><div class="stat"><b>${Number(x.risk_index).toFixed(0)}</b><div class="muted">Risk Index</div></div><div class="stat"><b>${Number(x.speed).toFixed(0)}</b><div class="muted">Speed</div></div><div class="stat"><b>${Number(x.urgency).toFixed(0)}</b><div class="muted">Urgency</div></div></div><p class="muted">Data Quality: ${Number(x.data_quality).toFixed(0)} · Quotes: ${x.counts.quotes} · Routes: ${x.counts.routes} · Open Actions: ${x.counts.open_actions} · Overdue: ${x.counts.overdue_actions}</p><ul>${(x.reasons||[]).map(r=>`<li>${esc(r)}</li>`).join('')}</ul><button class="ghost healthActionBtn" data-id="${esc(x.opportunity_id)}">اقدام‌های پیشنهادی</button><div id="health-actions-${esc(x.opportunity_id)}"></div></article>`).join('')||'<div class="card muted">Opportunity فعالی برای تحلیل وجود ندارد.</div>'}`;document.querySelectorAll('.healthActionBtn').forEach(b=>b.addEventListener('click',()=>loadHealthActions(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadHealthActions(id){const box=$('health-actions-'+id);if(!box)return;try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/health/actions');box.innerHTML=`<div class="mini"><b>اقدام‌های پیشنهادی</b>${(d.recommended_actions||[]).map(a=>`<p>${esc(a.priority)} · ${esc(a.action)} — ${esc(a.reason)}</p>`).join('')||'<span class="muted">اقدام ویژه‌ای شناسایی نشد.</span>'}</div>`}catch(e){showError(e.message)}}
async function opportunityPipeline(){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری Pipeline...</div>';try{const d=await api('/api/opportunities/pipeline');const stages=d.stages||{};const order=Object.keys(stages);$('results').innerHTML=`<div class="card"><h3>Opportunity Operating System · Pipeline</h3><p class="muted">هر فرصت از کشف تا نتیجه، با مسئول، موعد، شواهد و اقدام بعدی قابل پیگیری است.</p><div class="pipeline">${order.map(stage=>{const rows=stages[stage]||[];return `<section class="pipelineCol"><h4>${esc(stage)} <span class="chip">${rows.length}</span></h4>${rows.slice(0,12).map(o=>`<article class="mini pipelineCard"><b>#${esc(o.id)} · ${esc(Math.round(o.score||0))}</b><div>${esc(o.next_action||'بدون اقدام بعدی')}</div><small class="muted">${o.overdue?'⚠ سررسید گذشته · ':''}${o.days_in_stage!=null?Math.round(o.days_in_stage)+' روز در مرحله':''}</small><button class="ghost stageBtn" data-id="${esc(o.id)}">مدیریت</button></article>`).join('')||'<div class="muted">خالی</div>'}</section>`}).join('')}</div></div>`;document.querySelectorAll('.stageBtn').forEach(b=>b.addEventListener('click',()=>loadOperatingSystem(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadOperatingSystem(id){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری وضعیت عملیاتی...</div>';try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/operating-system');const cfg=d.stage_config||{};const stages=['Discovered','Verified','Qualified','RFQ Sent','Supplier Quoted','Logistics Priced','Commercial Offer','Negotiation','Won','Lost'];$('results').innerHTML=`<div class="card opp"><div class="brand">Opportunity #${esc(d.opportunity?.id)}</div><h3>مرحله فعلی: ${esc(d.stage)}</h3><div class="chain">${stages.map((x,i)=>`<span class="chip ${x===d.stage?'ok':''}">${i+1}. ${esc(x)}</span>`).join('')}</div><h4>شواهد لازم</h4>${Object.entries(d.evidence||{}).map(([k,v])=>`<p>${v?'✓':'—'} ${esc(k)}</p>`).join('')}<h4>اقدام‌های باز</h4>${(d.open_actions||[]).map(a=>`<div class="mini"><b>${esc(a.action_type)}</b> · ${esc(a.status)} · ${esc(a.subject||'')}</div>`).join('')||'<span class="muted">اقدام بازی وجود ندارد.</span>'}<h4>انتقال مرحله</h4><div class="grid"><select id="stageTarget">${stages.map(x=>`<option ${x===d.stage?'selected':''}>${esc(x)}</option>`).join('')}</select><input id="stageReason" placeholder="دلیل/یادداشت مرحله"><input id="stageDue" type="datetime-local"><input id="stageOwner" type="number" placeholder="ID مسئول (اختیاری)"></div><input id="stageNextAction" placeholder="Next Action (اختیاری)"><button id="stageSave" class="accent">ثبت تغییر مرحله</button><p class="muted">${esc(d.disclaimer||'')}</p></div>`;$('stageSave')?.addEventListener('click',async()=>{try{const due=$('stageDue').value?new Date($('stageDue').value).toISOString():null;const owner=$('stageOwner').value?Number($('stageOwner').value):null;const payload={stage:$('stageTarget').value,reason:$('stageReason').value||null,due_at:due,owner_id:owner,next_action:$('stageNextAction').value||null};await api('/api/opportunities/'+encodeURIComponent(id)+'/stage',{method:'POST',body:JSON.stringify(payload)});await loadOperatingSystem(id)}catch(e){showError(e.message)}})}catch(e){$('results').innerHTML='';showError(e.message)}}
async function generateRFQ(id){clearError();const box=$('rfq-'+id);if(!box)return;box.innerHTML='<div class="card">در حال ساخت پیام...</div>';try{const items=await Promise.all(['whatsapp','email','rfq'].map(channel=>api('/api/opportunities/'+id+'/rfq/generate',{method:'POST',body:JSON.stringify({channel,language:'en',tone:channel==='whatsapp'?'concise':'professional'})})));box.innerHTML=items.map(x=>`<div class="card"><b>${esc(x.title)}</b><pre>${esc(x.body)}</pre><button class="ghost sendRfq" data-rfq="${esc(x.id)}" data-op="${esc(id)}">ثبت به‌عنوان ارسال‌شده</button></div>`).join('')}catch(e){box.innerHTML='';showError(e.message)}}
async function loadComms(id){clearError();const box=$('rfq-'+id);if(!box)return;try{const d=await api('/api/opportunities/'+id+'/communications');box.innerHTML='<div class="card"><h4>سابقه ارتباطات</h4>'+(d.map(x=>`<p><b>${esc(x.channel)} · ${esc(x.status)}</b><br>${esc(x.message)}</p>`).join('')||'<span class="muted">ارتباطی ثبت نشده است.</span>')+'</div>'}catch(e){showError(e.message)}}
async function search(){const p=$('product').value.trim();if(!p)return showError('نام محصول را وارد کنید.');clearError();$('results').innerHTML='<div class="card">در حال جستجو...</div>';try{const d=await api('/api/search',{method:'POST',body:JSON.stringify({product:p,market:$('market').value})});$('results').innerHTML=`<div class="card"><h3>نتیجه: ${esc(d.product.name)}</h3><p class="muted">تولیدکنندگان: ${d.manufacturers.length} · مشتریان: ${d.customers.length} · تقاضا: ${d.demands.length}</p></div>${d.opportunities.map(o=>`<article class="card opp"><b>${esc(o.priority)} · ${esc(o.score)}</b><p>فاصله: ${o.distance_km?esc(Math.round(o.distance_km))+' km':'نامشخص'}</p><small class="muted">اقدام بعدی: ${esc(o.next_action)}</small><div class="grid actions"><button class="rfqBtn" data-id="${esc(o.id)}">ساخت پیام تجاری</button><button class="ghost commBtn" data-id="${esc(o.id)}">ارتباطات</button></div><div id="rfq-${esc(o.id)}"></div></article>`).join('')||'<div class="card muted">هنوز فرصت ثبت‌شده‌ای برای این محصول وجود ندارد.</div>'}` }catch(e){$('results').innerHTML='';showError(e.message)}}
init();
})();


async function sourceEvidenceCenter(){clearError();$('results').innerHTML='<div class="card">در حال تحلیل زنجیره شواهد...</div>';try{const d=await api('/api/source-intelligence/opportunities?limit=100');const items=d.items||[];$('results').innerHTML=`<div class="card"><h3>Source & Evidence Intelligence · V24.21</h3><p class="muted">اعتبار منبع، تازگی، استقلال منابع، تعارض ادعاها و زنجیره شواهد بررسی می‌شود؛ وجود یک منبع به‌تنهایی به معنی تأیید مشتری یا تقاضا نیست.</p></div>${items.map(x=>`<article class="card opp"><div class="row"><b>#${esc(x.opportunity_id)}</b><span class="chip">${esc(x.status)}</span></div><div class="stats"><div class="stat"><b>${Number(x.overall_score).toFixed(0)}</b><div class="muted">Evidence</div></div><div class="stat"><b>${x.independent_sources}</b><div class="muted">Sources</div></div><div class="stat"><b>${x.independent_domains}</b><div class="muted">Domains</div></div><div class="stat"><b>${x.conflict_count}</b><div class="muted">Conflicts</div></div></div><p class="muted">Source diversity: ${Number(x.source_diversity_score).toFixed(0)} · Avg trust: ${Math.round(Number(x.average_source_trust)*100)}%</p><ul>${(x.conflicts||[]).slice(0,4).map(c=>`<li>⚠ ${esc(c.entity_type)} · ${esc(c.claim_key)}: ${(c.values||[]).map(v=>esc(v.value)).join(' / ')}</li>`).join('')}${(x.recommendations||[]).map(r=>`<li>• ${esc(r.action)} — ${esc(r.reason)}</li>`).join('')}</ul><button class="ghost evidenceBtn" data-id="${esc(x.opportunity_id)}">جزئیات Evidence Chain</button><div id="evidence-${esc(x.opportunity_id)}"></div></article>`).join('')||'<div class="card muted">فرصت فعالی وجود ندارد.</div>'}`;document.querySelectorAll('.evidenceBtn').forEach(b=>b.addEventListener('click',()=>loadEvidenceDetail(b.dataset.id)))}catch(e){$('results').innerHTML='';showError(e.message)}}
async function loadEvidenceDetail(id){const box=$('evidence-'+id);if(!box)return;try{const d=await api('/api/opportunities/'+encodeURIComponent(id)+'/source-intelligence');box.innerHTML=`<div class="mini"><b>Evidence Chain</b>${Object.entries(d.entities||{}).map(([k,v])=>`<p><b>${esc(k)}</b> · ${v.chain.evidence_count} evidence · ${v.chain.independent_sources} independent sources · conflicts ${v.chain.conflict_count}</p>`).join('')}${(d.recommendations||[]).map(r=>`<p>⚠ ${esc(r.action)} — ${esc(r.reason)}</p>`).join('')}</div>`}catch(e){showError(e.message)}}

async function temporalIntelligence(){clearError();$('results').innerHTML='<div class="card">در حال تحلیل تغییرات زمانی فرصت‌ها...</div>';try{const d=await api('/api/temporal-intelligence/opportunities?days=90&limit=100');const items=d.items||[];$('results').innerHTML=`<div class="card"><h3>Temporal Market & Opportunity Intelligence · V24.21</h3><p class="muted">تغییرات زمانی قیمت، تازگی Buyer/Supplier/Demand، Benchmark، Verification و ماندگاری Opportunity بررسی می‌شود. این شاخص پیش‌بینی نتیجه معامله نیست.</p></div>${items.map(x=>`<article class="card opp"><div class="row"><b>#${esc(x.opportunity_id)} · ${esc(x.direction)}</b><span class="chip">${Number(x.temporal_score).toFixed(0)}</span></div><div class="stats"><div class="stat"><b>${esc(x.price_trend.direction)}</b><div class="muted">Price Trend</div></div><div class="stat"><b>${esc(x.price_observation_count)}</b><div class="muted">Observations</div></div><div class="stat"><b>${esc(x.benchmark.freshness_score.toFixed(0))}</b><div class="muted">Benchmark Freshness</div></div><div class="stat"><b>${esc(x.stage_age_days.toFixed(1))}</b><div class="muted">Stage Days</div></div></div><p class="muted">Buyer ${x.entities.customer.freshness_score.toFixed(0)} · Supplier ${x.entities.manufacturer.freshness_score.toFixed(0)} · Verification ${x.verification_freshness_score.toFixed(0)}</p><ul>${(x.signals||[]).map(v=>`<li>⚠ ${esc(v.message)}</li>`).join('')}${(x.recommendations||[]).map(v=>`<li>• ${esc(v.action)} — ${esc(v.reason)}</li>`).join('')}</ul><button class="ghost temporalDetailBtn" data-id="${esc(x.opportunity_id)}">جزئیات زمانی</button><div id="temporal-${esc(x.opportunity_id)}"></div></article>`).join('')||'<div class="card muted">Opportunity فعالی وجود ندارد.</div>'}`;document.querySelectorAll('.temporalDetailBtn').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.id;const box=$('temporal-'+id);try{const z=await api('/api/opportunities/'+encodeURIComponent(id)+'/temporal-intelligence?days=180');box.innerHTML=`<div class="mini"><b>Temporal Detail</b><p>Direction: ${esc(z.direction)} · Score: ${Number(z.temporal_score).toFixed(0)}</p><p>Price: ${esc(z.price_trend.direction)} · Change: ${esc(z.price_trend.change_pct??'—')}%</p><p>Stage age: ${Number(z.stage_age_days).toFixed(1)} days · Benchmark age: ${esc(z.benchmark.age_days??'—')}</p></div>`}catch(e){showError(e.message)}}))}catch(e){$('results').innerHTML='';showError(e.message)}}

