async function rbacCenter(){clearError();$('results').innerHTML='<div class="card">در حال بارگذاری مدیریت کاربران و دسترسی‌ها...</div>';try{const [users,roles]=await Promise.all([api('/api/admins'),api('/api/rbac/roles')]);$('results').innerHTML=`<div class="card"><div class="row"><div><h2>Users & Permissions · V24.21</h2><p class="muted">مدیریت نقش، فعال/غیرفعال‌سازی کاربر و مشاهده مجوزهای هر نقش.</p></div><button id="rbacRefresh" class="accent">به‌روزرسانی</button></div></div><div class="card"><h3>کاربران</h3>${users.map(u=>`<article class="mini"><div class="row"><b>${esc(u.username)}</b><span class="chip">${esc(u.role)}</span></div><p class="muted">وضعیت: ${u.is_active?'فعال':'غیرفعال'}</p><div class="grid"><select class="roleSel" data-id="${u.id}">${roles.map(r=>`<option ${r.role===u.role?'selected':''}>${esc(r.role)}</option>`).join('')}</select><button class="ghost roleSave" data-id="${u.id}">ذخیره نقش</button><button class="ghost statusSave" data-id="${u.id}" data-active="${u.is_active}">${u.is_active?'غیرفعال‌سازی':'فعال‌سازی'}</button></div></article>`).join('')}</div><div class="card"><h3>مجوزهای نقش‌ها</h3>${roles.map(r=>`<article class="mini"><b>${esc(r.role)}</b><p class="muted">${r.permissions.map(esc).join(' · ')}</p></article>`).join('')}</div>`;$('rbacRefresh')?.addEventListener('click',rbacCenter);document.querySelectorAll('.roleSave').forEach(b=>b.addEventListener('click',async()=>{const sel=document.querySelector('.roleSel[data-id="'+b.dataset.id+'"]');try{await api('/api/admins/'+b.dataset.id+'/role',{method:'PATCH',body:JSON.stringify({role:sel.value})});await rbacCenter()}catch(e){showError(e.message)}}));document.querySelectorAll('.statusSave').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/admins/'+b.dataset.id+'/status',{method:'PATCH',body:JSON.stringify({is_active:b.dataset.active!=='true'})});await rbacCenter()}catch(e){showError(e.message)}}))}catch(e){showError(e.message)}}
